contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool open, uint256 amount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);

        // Setup: optionally make the game open to the public.
        if (open) {
            c.OpenToThePublic();
        }

        uint256 beforeBal = address(c).balance;

        // Deciding call: donate with the given amount.
        bool reverted;
        try c.donate{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: donate succeeds iff open, and on success the balance increases by amount.
        if (open) {
            assert(!reverted && address(c).balance == beforeBal + amount);
        } else {
            assert(reverted && address(c).balance == beforeBal);
        }
    }

    receive() external payable {}
}

